package dev.industrialtechnology.spacecheck;
import java.util.function.BiConsumer;import net.minecraft.world.*;import net.minecraft.entity.player.*;import net.minecraft.item.*;import net.minecraft.init.Blocks;import net.minecraft.tileentity.TileEntity;import net.minecraftforge.common.*;import net.minecraftforge.common.util.*;import net.minecraftforge.event.entity.player.PlayerInteractEvent;import cpw.mods.fml.common.eventhandler.SubscribeEvent;import com.hbm.blocks.ModBlocks;import com.hbm.tileentity.network.TileEntityPipeBaseNT;import com.hbm.tileentity.machine.storage.TileEntityMachineFluidTank;import com.hbm.inventory.fluid.*;import com.hbm.uninos.*;import api.hbm.fluidmk2.*;import dev.industrialtechnology.space.*;
/** Real native storage + two real native pipes. No fabricated provider or manual source debit. */
public final class ShuttleHbmChecks {
    private static void check(boolean b,String s){SpaceChecks.check(b,s);}
    private static final class Fixture {TileEntityMachineFluidTank tank;TileSpaceMachine pad;int x,y,z;ForgeDirection d;FluidType type;FluidNetMK2 net;TileEntityPipeBaseNT first;}
    public static final class Claim {boolean active;@SubscribeEvent public void interact(PlayerInteractEvent e){if(active)e.setCanceled(true);}}
    private static Fixture fixture(WorldServer w,EntityPlayerMP p,int origin,FluidType type){
        for(int x=origin-8;x<=origin+8;x++)for(int z=392;z<=408;z++){w.getChunkFromChunkCoords(x>>4,z>>4);w.setBlock(x,69,z,Blocks.stone,0,3);for(int y=70;y<=76;y++)w.setBlockToAir(x,y,z);}
        w.setBlock(origin,70,400,ModBlocks.machine_fluidtank,0,3);p.rotationYaw=0;ModBlocks.machine_fluidtank.onBlockPlacedBy(w,origin,70,400,p,new ItemStack(ModBlocks.machine_fluidtank));Fixture f=new Fixture();f.type=type;
        for(int x=origin-6;x<=origin+6;x++)for(int y=70;y<=74;y++)for(int z=394;z<=406;z++){TileEntity te=w.getTileEntity(x,y,z);if(te instanceof TileEntityMachineFluidTank)f.tank=(TileEntityMachineFluidTank)te;}check(f.tank!=null,"native tank core missing");
        outer:for(int x=origin-6;x<=origin+6;x++)for(int y=70;y<=74;y++)for(int z=394;z<=406;z++){TileEntity te=w.getTileEntity(x,y,z);if(te==f.tank||dev.industrialtechnology.wireless.HbmFluidAccess.storage(te)!=f.tank)continue;for(ForgeDirection d:ForgeDirection.VALID_DIRECTIONS){if(d.offsetY!=0)continue;boolean free=true;for(int n=1;n<=3;n++)if(!w.isAirBlock(x+d.offsetX*n,y,z+d.offsetZ*n))free=false;if(free){f.x=x+d.offsetX;f.y=y;f.z=z+d.offsetZ;f.d=d;break outer;}}}check(f.d!=null,"no native tank port");
        f.tank.mode=1;f.tank.tank.setTankType(type);f.tank.tank.setFill(5000);for(int n=0;n<2;n++){int x=f.x+f.d.offsetX*n,z=f.z+f.d.offsetZ*n;w.setBlock(x,f.y,z,ModBlocks.fluid_duct_neo,0,3);TileEntityPipeBaseNT pipe=(TileEntityPipeBaseNT)w.getTileEntity(x,f.y,z);pipe.setType(type);pipe.updateEntity();if(n==0)f.first=pipe;}
        int x=f.x+f.d.offsetX*2,z=f.z+f.d.offsetZ*2;w.setBlock(x,f.y,z,SpaceRegistry.machines[SpaceRegistry.PORT],0,3);f.pad=(TileSpaceMachine)w.getTileEntity(x,f.y,z);f.pad.owner=p.getUniqueID().toString();UniNodespace.updateNodespace();w.getWorldInfo().incrementTotalWorldTime((w.getTotalWorldTime()/20+1)*20);HbmPipeAdapter.tick(f.pad);GenNode node=UniNodespace.getNode(w,f.x,f.y,f.z,type.getNetworkProvider());check(node!=null&&node.hasValidNet(),"native pipe network missing");f.net=(FluidNetMK2)node.net;return f;
    }
    private static void flow(WorldServer w,Fixture f){((IFluidStandardSenderMK2)(Object)f.tank).tryProvide(f.type,0,w,f.x,f.y,f.z,f.d);f.net.update();}
    public static void run(WorldServer w,EntityPlayerMP p,BiConsumer<String,Runnable> test){
        test.accept("Planetary concentrates craft actual HBM titanium and aluminium ingots, not substitute items",()->{for(int k=0;k<2;k++){net.minecraft.inventory.InventoryCrafting grid=new net.minecraft.inventory.InventoryCrafting(new net.minecraft.inventory.Container(){public boolean canInteractWith(net.minecraft.entity.player.EntityPlayer p){return true;}},3,3);for(int i=0;i<9;i++)grid.setInventorySlotContents(i,new ItemStack(k==0?PlanetResources.titaniumFraction:PlanetResources.aluminiumFraction));ItemStack output=net.minecraft.item.crafting.CraftingManager.getInstance().findMatchingRecipe(grid,w);check(output!=null&&output.getItem()==HbmSpaceBridge.material(k==0?"ingot_titanium":"ingot_aluminium"),"HBM ingot identity mismatch "+k);}});
        test.accept("Genuine HBM kerosene pipes debit source and fill launch fuel port with exact shared tick limit",()->{Fixture f=fixture(w,p,1900,Fluids.KEROSENE);flow(w,f);check(f.tank.tank.getFill()==4500&&f.pad.tanks[0].getFluidAmount()==500,"native kerosene balance source="+f.tank.tank.getFill()+" pad="+f.pad.tanks[0].getFluidAmount());flow(w,f);flow(w,f);check(f.tank.tank.getFill()==4000&&f.pad.tanks[0].getFluidAmount()==1000,"same tick limit bypass");w.getWorldInfo().incrementTotalWorldTime(w.getTotalWorldTime()+1);f.pad.tanks[0].setFluid(new net.minecraftforge.fluids.FluidStack(SpaceRegistry.kerosene,SpaceConfig.tankCapacity-123));flow(w,f);check(f.tank.tank.getFill()==3877&&f.pad.tanks[0].getFluidAmount()==SpaceConfig.tankCapacity,"partial native debit");w.getWorldInfo().incrementTotalWorldTime(w.getTotalWorldTime()+1);flow(w,f);check(f.tank.tank.getFill()==3877,"full tank drained source");});
        test.accept("HBM cryogenic OXYGEN pipes fill separate liquid oxygen tank directly",()->{Fixture f=fixture(w,p,1950,Fluids.OXYGEN);flow(w,f);check(f.tank.tank.getFill()==4500&&f.pad.tanks[1].getFluidAmount()==500&&f.pad.tanks[0].getFluidAmount()==0,"native LOX balance");check(f.pad.getDemand(Fluids.WATER,0)==0&&f.pad.getDemand(Fluids.OXYGEN,1)==0,"wrong fluid/pressure accepted");w.getWorldInfo().incrementTotalWorldTime(w.getTotalWorldTime()+1);f.pad.enabled=false;flow(w,f);check(f.tank.tank.getFill()==4500,"disabled receiver consumed fluid");f.pad.enabled=true;Claim claim=new Claim();MinecraftForge.EVENT_BUS.register(claim);try{claim.active=true;flow(w,f);check(f.tank.tank.getFill()==4500,"protected pipe transfer");}finally{MinecraftForge.EVENT_BUS.unregister(claim);}w.setBlockToAir(f.pad.xCoord-f.d.offsetX,f.pad.yCoord,f.pad.zCoord-f.d.offsetZ);check(f.pad.getDemand(Fluids.OXYGEN,0)==0,"broken connection retained demand");f.pad.onChunkUnload();check(f.pad.transferFluid(Fluids.OXYGEN,0,100)==100,"unloaded receiver accepted");});
        test.accept("Native HBM pipe can attach directly to LC39 root as well as existing fuel port",()->{TileLaunchFacility t=(TileLaunchFacility)w.getTileEntity(400,6,400);int x=399,y=6,z=400;w.setBlock(x,y,z,ModBlocks.fluid_duct_neo,0,3);TileEntityPipeBaseNT pipe=(TileEntityPipeBaseNT)w.getTileEntity(x,y,z);pipe.setType(Fluids.KEROSENE);pipe.updateEntity();UniNodespace.updateNodespace();w.getWorldInfo().incrementTotalWorldTime((w.getTotalWorldTime()/20+1)*20);HbmPipeAdapter.tick(t);check(t instanceof IFluidReceiverMK2&&t.getDemand(Fluids.KEROSENE,0)>0,"LC39 root is not native pipe receiver");w.setBlockToAir(x,y,z);});
    }
}
